import {describe, expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

describe('beforeSession failure', () => {
  // specs/hal-engine-config-hooks/spec.md#7
  it('passes the session and error to onError when beforeSession fails', async () => {
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const error = new Error('beforeSession failed');
    let received: unknown;
    const orchestrator = createChatOrchestrator({} as AIProvider, new PromptBuilder({identity: 'test'}), undefined, {
      hooks: {
        beforeSession: async () => { throw error; },
        onError: async (hookSession, hookError) => { received = [hookSession, hookError]; },
      },
    });
    await orchestrator.processMessage(session).catch(() => undefined);
    expect(received).toEqual([session, error]);
  });
});
EOF
 timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runInBand --runTestsByPath src/orchestration/chatOrchestrator.beforeSession.test.ts"
